insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'lettuce'), 'soil', 'soil_prep', 'تجهيز التربة للخس', 'تربة خصبة مفككة؛ في الأصص يكفي عمق 15–20 سم.', -5, null, null, '{}'::int[], 0) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'lettuce'), 'plant', 'planting', 'شتل الخس', 'ازرع الأشتال على مستوى سطح التربة دون دفن القلب، واروِ مباشرة.', 0, null, null, '{}'::int[], 1) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'lettuce'), 'water', 'irrigation', 'متابعة ري الخس', 'افحص رطوبة التربة بإصبعك على عمق 3–5 سم واروِ عند جفافها فقط. تجاوز المهمة إذا هطلت أمطار كافية أو كانت التربة رطبة؛ فالحاجة الفعلية تتأثر بنوع التربة والطقس وعمر النبات.', 1, 2, 70, '{}'::int[], 2) on conflict (crop_id, key) do nothing;
