insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'lettuce'), 'pests', 'pest_check', 'فحص الخس', 'ابحث عن البزاقات والحلزون، خاصة بعد الري أو المطر، وعن المن داخل القلب.', 7, 7, 70, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'lettuce'), 'harvest', 'harvest', 'بداية قطف الخس المتوقع', 'يمكن قطف الأوراق الخارجية تدريجيًا، أو قطع الرأس كاملًا عند اكتماله وقبل الإزهار.', 45, null, null, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'overview', 'نظرة عامة', 'الخس نبات ورقي يحب الجو المعتدل والبارد. في الحر يتجه للإزهار (الحنبلة) وتصبح أوراقه مُرّة.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'planting', 'الزراعة', 'يُزرع بالبذر أو بالأشتال. في الساحل يُزرع طوال الموسم البارد، وفي المرتفعات في الربيع والخريف.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'care', 'العناية', 'يستفيد من ظل جزئي في الأيام الدافئة. الزراعة المتتابعة كل أسبوعين تضمن إنتاجًا مستمرًا.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'irrigation', 'الري', 'جذور سطحية تحتاج إلى رطوبة منتظمة خفيفة، مع تجنب تجمع الماء.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'fertilization', 'التسميد', 'تسميد خفيف يكفي؛ الإفراط في الآزوت قد يرفع تراكم النترات في الأوراق.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'harvest', 'الحصاد', 'بعد 45–75 يومًا تقريبًا. القطف الصباحي يحافظ على قرمشة الأوراق.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'problems', 'المشكلات الشائعة', 'البزاقات والحلزون، والمن، والإزهار المبكر في الحر، واحتراق حواف الأوراق.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'problems');
