insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'overview', 'نظرة عامة', 'النعناع عشبة معمّرة تنتشر بالجذامير بسرعة، ولذلك يُفضّل في الأصص. يتحمل الظل الجزئي جيدًا.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'planting', 'الزراعة', 'يُكثّر بسهولة بالعُقَل أو تقسيم الجذامير في الربيع والخريف.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'care', 'العناية', 'التقليم المنتظم يحافظ على كثافة النبات. جدّد النبات كل بضع سنوات.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'irrigation', 'الري', 'يحب الرطوبة؛ في الصيف قد يحتاج الأصيص إلى متابعة يومية حسب حجمه ومكانه.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'fertilization', 'التسميد', 'إضافة كمبوست خفيف كل بضعة أشهر تكفي غالبًا.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'mint'), 'harvest', 'الحصاد', 'يمكن القطف المتكرر بعد أن يثبت النبات ويتفرع.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'mint') and x.section = 'harvest');
