insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'strawberry'), 'runners', 'care', 'إزالة المدادات الزائدة', 'أزل المدادات (السيقان الزاحفة) ليركّز النبات على الإثمار، أو اتركها إن أردت الإكثار.', 30, null, null, '{}'::int[], 3) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'strawberry'), 'fert', 'fertilizing', 'تسميد الفراولة', 'تسميد معتدل قبل الإزهار.', 40, null, null, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'strawberry'), 'pests', 'pest_check', 'فحص الفراولة', 'راقب العفن الرمادي على الثمار، والعنكبوت الأحمر، والبزاقات.', 14, 10, 150, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'strawberry'), 'harvest', 'harvest', 'بداية قطف الفراولة المتوقع', 'اقطف الثمار عند اكتمال لونها الأحمر، ويفضل صباحًا.', 60, null, null, '{}'::int[], 6) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'overview', 'نظرة عامة', 'الفراولة نبات معمّر يُزرع عادةً كمحصول موسمي لتجديد الإنتاج. يحب الشمس والجو المعتدل.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'planting', 'الزراعة', 'الشتل في الخريف هو الشائع في المناطق المعتدلة، مع إمكانية الزراعة الربيعية في المرتفعات.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'care', 'العناية', 'تغطية التربة تحمي الثمار من ملامسة التربة وتقلل العفن. أزل الأوراق الجافة والمصابة.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'irrigation', 'الري', 'رطوبة منتظمة؛ الري بالتنقيط أو عند القاعدة أفضل من الرش.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'fertilization', 'التسميد', 'تسميد معتدل قبل الإزهار وخلال الإثمار.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'harvest', 'الحصاد', 'يمتد القطف عدة أسابيع أو أشهر حسب الصنف والطقس.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'strawberry'), 'problems', 'المشكلات الشائعة', 'العفن الرمادي، والعنكبوت الأحمر، والبزاقات، وتعفن التاج عند دفنه أو الإفراط في الري.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'strawberry') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note) values ('olive', 'الزيتون', '{}'::text[], 'Olea europaea', 'tree', 'perennial', 'medium', 'full_sun', 'low', false, array['home_garden','small_plot','farm']::text[], null, null, 'شجرة معمّرة؛ تبدأ الغراس عادةً بالإثمار بعد عدة سنوات من الزراعة، ويختلف ذلك حسب الصنف والعناية.', 'شجرة الأرض الفلسطينية، تتحمل الجفاف وتعيش طويلًا. تُزرع الغراس عادةً في موسم الأمطار.', 'الغراس الصغيرة تحتاج إلى ري في صيفها الأول والثاني، ثم تعتمد غالبًا على الأمطار.', 'غصن زيتون مع ثمار خضراء', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.') on conflict (slug) do nothing;
